{"context":{"snapshot":"f9026a7607eb9b3542b1918c3360d3718c8c1bda","sources":{"packages/cli/lib/fly.js":"1: 'use strict';
2: const fs = require('fs');
3: const os = require('os');
4: const path = require('path');
5: const { spawnSync } = require('child_process');
6: 
7: function flyctlBin() {
8:   const local = path.join(os.homedir(), '.fly', 'bin', process.platform === 'win32' ? 'flyctl.exe' : 'flyctl');
9:   return fs.existsSync(local) ? local : 'flyctl'; // fall back to PATH
10: }
11: 
12: function flyEnv(token) {
13:   return { ...process.env, FLY_API_TOKEN: token, FLY_ACCESS_TOKEN: token, FLY_NO_UPDATE_CHECK: '1' };
14: }
15: 
16: function run(args, token, { capture = false, cwd } = {}) {
17:   const r = spawnSync(flyctlBin(), args, {
18:     env: flyEnv(token),
19:     cwd,
20:     stdio: capture ? ['ignore', 'pipe', 'pipe'] : 'inherit',
21:     encoding: 'utf8',
22:   });
23:   if (r.error && r.error.code === 'ENOENT') {
24:     throw new Error('flyctl not installed — https://fly.io/docs/flyctl/install/');
25:   }
26:   return r;
27: }
28: 
29: function setSecrets(flyApp, token, kv) {
30:   const pairs = Object.entries(kv).map(([k, v]) => `${k}=${v}`);
31:   if (!pairs.length) return;
32:   const r = run(['secrets', 'set', '--app', flyApp, '--stage', ...pairs], token, { capture: true });
33:   const out = (r.stdout || '') + (r.stderr || '');
34:   if (r.status !== 0 && !/no change/i.test(out)) throw new Error(`flyctl secrets set failed:\n${out.trim()}`);
35: }
36: 
37: function deploy(flyApp, token, cwd) {
38:   const r = run(
39:     ['deploy', '.', '--app', flyApp, '--config', '.small/fly.toml', '--dockerfile', '.small/Dockerfile', '--remote-only', '--ha=false', '--yes'],
40:     token,
41:     { cwd }
42:   );
43:   if (r.status !== 0) throw new Error('deploy failed — see flyctl output above');
44: }
45: 
46: function logs(flyApp, token) {
47:   run(['logs', '--app', flyApp, '--no-tail'], token);
48: }
49: 
50: module.exports = { setSecrets, deploy, logs };","packages/control-plane/src/fly.js":"1: // Fly control from the worker. The org admin token (env.FLY_API_TOKEN) never
2: // leaves this process; the CLI only ever receives 1h app-scoped deploy tokens.
3: // Chosen over building from a tarball here: Fly has no build-from-tarball REST
4: // endpoint — remote builds speak the Docker/BuildKit protocol to a builder
5: // machine, which a Worker cannot. See docs/v3.
6: const MACHINES = 'https://api.machines.dev/v1';
7: const GQL = 'https://api.fly.io/graphql';
8: 
9: const authH = (env) => (env.FLY_API_TOKEN.startsWith('FlyV1') ? env.FLY_API_TOKEN : `Bearer ${env.FLY_API_TOKEN}`);
10: 
11: async function gql(env, query, variables) {
12:   const resp = await fetch(GQL, {
13:     method: 'POST',
14:     headers: { Authorization: authH(env), 'Content-Type': 'application/json' },
15:     body: JSON.stringify({ query, variables }),
16:   });
17:   const body = await resp.json();
18:   if (body.errors) throw new Error(`fly graphql: ${body.errors[0].message}`);
19:   return body.data;
20: }
21: 
22: // Create the Fly app + shared IPv4. Idempotent — rerun on every deploy.
23: export async function ensureFlyApp(env, flyApp) {
24:   const resp = await fetch(`${MACHINES}/apps`, {
25:     method: 'POST',
26:     headers: { Authorization: authH(env), 'Content-Type': 'application/json' },
27:     body: JSON.stringify({ app_name: flyApp, org_slug: env.FLY_ORG_SLUG || 'personal' }),
28:   });
29:   if (!resp.ok) {
30:     const text = await resp.text();
31:     if (!/taken|already/i.test(text)) throw new Error(`fly app create failed (${resp.status}): ${text}`);
32:   }
33:   await gql(env, 'mutation($app: ID!) { allocateIpAddress(input: {appId: $app, type: shared_v4}) { app { name } } }', { app: flyApp });
34: }
35: 
36: let orgIdCache;
37: async function orgId(env) {
38:   if (!orgIdCache) {
39:     const { organizations } = await gql(env, 'query { organizations { nodes { id slug type } } }');
40:     const slug = env.FLY_ORG_SLUG || 'personal';
41:     const node = organizations.nodes.find((n) => n.slug === slug) || organizations.nodes.find((n) => n.type === 'PERSONAL');
42:     if (!node) throw new Error(`no fly org matching ${slug}`);
43:     orgIdCache = node.id;
44:   }
45:   return orgIdCache;
46: }
47: 
48: // The only Fly credential the CLI ever sees: deploy-scoped to one app, dead in 1h.
49: export async function mintDeployToken(env, flyApp) {
50:   const data = await gql(
51:     env,
52:     'mutation($input: CreateLimitedAccessTokenInput!) { createLimitedAccessToken(input: $input) { limitedAccessToken { tokenHeader } } }',
53:     { input: { name: `small-${flyApp}`, organizationId: await orgId(env), profile: 'deploy', profileParams: { app_id: flyApp }, expiry: '1h0m0s' } }
54:   );
55:   return data.createLimitedAccessToken.limitedAccessToken.tokenHeader;
56: }"}},"question":"Why one hour rather than thirty minutes for the deploy token? Is there a recorded experiment choosing that duration?"}
